package net.minecraft.nbt;import java.util.*;public class CompoundTag{Map<String,Object> v=new HashMap<>();public void putLong(String k,long n){v.put(k,n);}public long getLong(String k){return ((Number)v.getOrDefault(k,0)).longValue();}public void putBoolean(String k,boolean n){v.put(k,n);}public boolean getBoolean(String k){return Boolean.TRUE.equals(v.get(k));}public void remove(String k){v.remove(k);}}
